#!/usr/bin/env python3
"""Build the distance/area measurement release report."""
from pathlib import Path
import base64,json
root=Path(__file__).resolve().parents[1]
version=json.loads((root/'package.json').read_text())['version']
def image(stage,caption):
 data=base64.b64encode((root/'qa'/f'v160-{stage}.png').read_bytes()).decode()
 return f'<figure><img alt="{caption}" src="data:image/png;base64,{data}"><figcaption>{caption} Actual SVG canvas geometry, not a browser UI screenshot.</figcaption></figure>'
html=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>INTERFACEBENCH {version} — Measure distance and area</title><style>body{{max-width:1040px;margin:40px auto;padding:0 24px;font:16px/1.6 system-ui;color:#233a2c;background:#f5f6ef}}h1{{font-size:38px;line-height:1.15}}h2{{margin-top:30px}}img{{width:100%;height:auto;border:1px solid #bbcbb7;border-radius:8px}}figure{{margin:24px 0}}figcaption,small{{font-size:13px;color:#526957}}.note{{padding:18px;background:#e4eadb}}li{{margin-bottom:8px}}</style><h1>Measure distance.<br>Click an outline for area.</h1><p>INTERFACEBENCH <strong>{version}</strong> · 2026-10-09</p><p>Measure now has an explicit active button, crosshair cursor, canvas border and control strip. Its first point is visible immediately, with a live segment and named snap target as you aim the next point.</p><ol><li>Choose <strong>Distance</strong> for two points or <strong>Area</strong> for a polygon.</li><li>Choose Features + grid, Features only, Grid only or Free points. Hold Shift for a horizontal/vertical segment and Alt to bypass snapping.</li><li>Use <strong>Enter point…</strong> for exact front-reference X/Y coordinates, including mm/cm/in suffixes.</li><li>Close an area by clicking point 1, clicking Finish area, pressing Enter, or double-clicking the final point. Read area and perimeter.</li><li>Undo point, Backspace or Ctrl/Command Z removes the last point. New clears; Done returns to selection. Escape clears, then exits on the next press.</li></ol><h2>Reviewed feedback</h2>{image('first-point','The first clicked point receives a numbered marker.')}{image('distance-preview','Live distance preview with an exact component-reference snap.')}{image('area','Completed four-point area: 9450 mm²; perimeter 410 mm.')}<h2>Precision and limits</h2><p>Snapping uses panel/component/cutout centres, corners, midpoints, circle quadrants and straight/circular edges. Rear view snaps to the rear body while preserving physical coordinates. Imported Bézier curves supply endpoint and parameter-midpoint targets. Area follows straight segments between points; tracing a curved border gives a polygon approximation. Crossed and zero-area polygons cannot be finalized.</p><p>Measurements are temporary editor overlays. They do not move parts, save constraints or enter fabrication outputs.</p><h2>Verification</h2><p><strong>91 automated checks pass.</strong> Fifteen new checks cover snapping geometry, valid/invalid polygon calculations, square-unit conversion, first-point/live rendering and application event workflows, including point undo, exact entry, rear coordinates and pan/cancel protection.</p><p class="note">Real-browser layout, native interaction, mobile and offline acceptance remain pending under the existing supported-browser restriction. This is a release candidate.</p><h2>Install</h2><p>Upload the complete extracted server ZIP to <code>/interfacebench/</code>. Back up project JSON before updating and use Save &amp; reload when offered. No build step or project migration is required.</p><small>GPL-3.0-only · 267 components · local-first · no telemetry</small></html>'''
report=root.parent/'output'/f'INTERFACEBENCH-v{version}-release-report.html'
report.write_text(html);print(report)
